static int get_team(game* thisGame, int playerNum)
{
    if (playerNum < 0)
        return playerNum;
    return thisGame->mapHeader.teamInfo[playerNum];
}

static bool same_team(game* thisGame, int firstPlayer, int secondPlayer)
{
    if (firstPlayer < 0 || secondPlayer < 0)
        return false;
    return thisGame->mapHeader.teamInfo[firstPlayer]
        == thisGame->mapHeader.teamInfo[secondPlayer];
}

